-- Keep one compact embedded track for the UI music player.
MusicPlayer.Database = {}
-- ===== embedded UI tracks =====
-- The mp3s are stored inside this script as base64 and written to UhhhhhhReanim/Assets/ the first
-- time the script runs (same trick as the intro track), so there is nothing to copy by hand.
-- The track is listed in "UI Music" / "Random UI Music".
do
	local function DecodeBase64(data)
		local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
		local lookup = {}
		for i = 1, 64 do
			lookup[string.byte(alphabet, i)] = i - 1
		end
		data = string.gsub(data, "[^%w%+/=]", "")
		local out, n = {}, 0
		for i = 1, #data, 4 do
			local a, b, c, d = string.byte(data, i, i + 3)
			local va, vb = lookup[a], lookup[b]
			local vc, vd = c and lookup[c], d and lookup[d]
			local n24 = va * 262144 + vb * 4096 + (vc or 0) * 64 + (vd or 0)
			n = n + 1
			if vc == nil then
				out[n] = string.char(math.floor(n24 / 65536))
			elseif vd == nil then
				out[n] = string.char(math.floor(n24 / 65536), math.floor(n24 / 256) % 256)
			else
				out[n] = string.char(math.floor(n24 / 65536), math.floor(n24 / 256) % 256, n24 % 256)
			end
			if n % 60000 == 0 then task.wait() end -- big file: do not hog the frame
		end
		return table.concat(out)
	end
