	local function DecodeBase64(data)
		local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
		local lookup = {}
		for i = 1, 64 do
			lookup[string.byte(alphabet, i)] = i - 1
		end
		data = string.gsub(data, "[^%w%+/=]", "")
		local out, n = {}, 0
		for i = 1, #data, 4 do
			local a, b, c, d = string.byte(data, i, i + 3)
			local va, vb = lookup[a], lookup[b]
			local vc, vd = c and lookup[c], d and lookup[d]
			local n24 = va * 262144 + vb * 4096 + (vc or 0) * 64 + (vd or 0)
			n = n + 1
			if vc == nil then
				out[n] = string.char(math.floor(n24 / 65536))
			elseif vd == nil then
				out[n] = string.char(math.floor(n24 / 65536), math.floor(n24 / 256) % 256)
			else
				out[n] = string.char(math.floor(n24 / 65536), math.floor(n24 / 256) % 256, n24 % 256)
			end
		end
		return table.concat(out)
	end
	GetIntroTrackAsset = function()
		local ok, asset = pcall(function()
			if not isfile(IntroTrackFile) or #readfile(IntroTrackFile) ~= IntroTrackSize then
				writefile(IntroTrackFile, DecodeBase64(IntroTrackB64))
			end
			return getcustomasset(IntroTrackFile)
		end)
		if ok and type(asset) == "string" then
			return asset
		end
		return ""
	end
end

-- if you put a song with "nyan" in its name (e.g. Nyan_Cat.mp3) in UhhhhhhReanim/Muzik/,
-- the intro plays it when the cat scene starts instead of the built-in retro track
local function FindNyanTrack()
	local s, files = pcall(listfiles, "UhhhhhhReanim/Muzik")
	if s and type(files) == "table" then
		for _, f in ipairs(files) do
			local fname = tostring(f):gsub("\\", "/"):match("([^/]+)$")
			if fname then
				local l = fname:lower()
				if l:find("nyan", 1, true) and (l:match("%.mp3$") or l:match("%.ogg$")) then
					local ok, asset = pcall(getcustomasset, "UhhhhhhReanim/Muzik/" .. fname)
					if ok and type(asset) == "string" and #asset > 0 then
						return asset
					end
				end
			end
		end
	end
	return ""
end

-- Scene made from your own video: put frames named nyanscene1.jpg, nyanscene2.jpg, ... (or .png,
-- up to 120) in UhhhhhhReanim/Assets/. They are played full screen in place of the drawn scene,
-- and the intro is stretched to the length of the clip.
local SCENE_FPS = 12
local ContentProviderService = cloneref(game:GetService("ContentProvider"))
local function FindSceneFrames()
	local frames = {}
	for i = 1, 120 do
		local found = ""
		for _, ext in ipairs({"jpg", "png"}) do
			local a = Util.GetCDNAsset("nyanscene" .. i .. "." .. ext)
			if #a > 0 then
				found = a
				break
			end
		end
		if #found == 0 then break end
		frames[#frames + 1] = found
	end
	return frames
end

SaveData.SkipIntro = not not SaveData.SkipIntro
MusicPlayer.IntroHasMusic = #MusicPlayer.Database > 0
MusicPlayer.IntroStart = os.clock()
if SaveData.SkipIntro then
	MusicPlayer.PlayMusic()
else
	-- the intro plays its own retro track on a separate Sound; the UI music list is untouched
	-- and the normal UI music fades in when the intro is over (see the end of this block)
	UISound.Music.Volume = 0
	local IntroSound = Util.Instance("Sound", UIMainFrame)
	IntroSound.Name = "IntroTrack"
	IntroSound.Looped = false
	IntroSound.PlaybackRegionsEnabled = false
	IntroSound.Volume = 1
	local NyanAsset = FindNyanTrack()
	local NyanDelayedPlay = #NyanAsset > 0 -- custom song: it starts together with the cat scene
	local NyanPlayed = false
	local NyanHold = NyanDelayedPlay and 3 or 0 -- a few extra seconds so the song is not cut right away
	local SceneFrames = FindSceneFrames()
	if #SceneFrames > 0 then
		-- the cat scene lasts 4.15 s by default; stretch the intro to fit the whole clip
		NyanHold = math.max(0, #SceneFrames / SCENE_FPS - 4.15)
	end
	local introasset = NyanDelayedPlay and NyanAsset or GetIntroTrackAsset()
	MusicPlayer.IntroHasMusic = #introasset > 0
	MusicPlayer.IntroStart = os.clock()
	if MusicPlayer.IntroHasMusic then
		IntroSound.SoundId = introasset
		local waited = 0
		repeat
			waited += RunService.RenderStepped:Wait()
		until IntroSound.IsLoaded or waited > 6
		IntroSound.TimePosition = 0
		if NyanDelayedPlay then
			-- nothing plays during the BIOS part; the intro loop starts the song (see below)
			MusicPlayer.IntroStart = os.clock()
		else
			IntroSound:Play()
			-- line the intro clock up with the real playhead so the animation hits the beats
			waited = 0
			repeat
				waited += RunService.RenderStepped:Wait()
			until IntroSound.TimePosition > 0 or waited > 1
			MusicPlayer.IntroStart = os.clock() - IntroSound.TimePosition
		end
	else
		-- intro track could not be written: fall back to the normal UI music during the intro
		UISound.Music.Volume = 1
		task.spawn(MusicPlayer.PlayMusic)
	end
	-- ===== retro intro, 3 stages: 1) BIOS POST  2) boot manager / kernel log  3) NYAN CAT + glitch title + loading bar =====
	local IntroRoot = nil
	local IntroConn = nil
	local function RunRetroIntro()
		local BOOT_EXTRA = 1.6
		local T_END = 6.4 + BOOT_EXTRA + NyanHold
		local MAGENTA = Color3.fromRGB(255, 45, 200)
		local CYAN = Color3.fromRGB(0, 235, 255)
		local YELLOW = Color3.fromRGB(255, 225, 80)
		local GREEN = Color3.fromRGB(90, 255, 120)
		local WHITE = Color3.new(1, 1, 1)
		local BLACK = Color3.new(0, 0, 0)
		local rng = Random.new()

		local function new(class, parent, props)
			local o = Util.Instance(class, parent)
			for k, v in props do
				o[k] = v
			end
			return o
		end

		local scr = Util.GetScreenSize()
		local W, H = scr.X, scr.Y

		local root = new("Frame", UIMainFrame, {
			Size = UDim2.new(1, 0, 1, 0),
			BackgroundColor3 = BLACK,
			BorderSizePixel = 0,
			ClipsDescendants = true,
			ZIndex = 1,
		})
		IntroRoot = root

		-- skip with a click, tap, space or enter
		local skip = false
		IntroConn = UserInputService.InputBegan:Connect(function(input)
			local ut = input.UserInputType
			if ut == Enum.UserInputType.MouseButton1 or ut == Enum.UserInputType.Touch
				or input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.Return then
				skip = true
			end
		end)

		-- CRT power-on line
		local crt = new("Frame", root, {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(0.5, 0, 0.5, 0),
			Size = UDim2.new(0, 0, 0, 3),
			BackgroundColor3 = WHITE,
			BorderSizePixel = 0,
			ZIndex = 90,
		})

		-- BIOS boot text
		local boot = new("TextLabel", root, {
			BackgroundTransparency = 1,
			Position = UDim2.new(0, 24, 0, 20),
			Size = UDim2.new(0.8, 0, 0.5, 0),
			Font = Enum.Font.Arcade,
			Text = "",
			TextColor3 = Color3.fromRGB(205, 205, 205),
			TextSize = 16,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Top,
			ZIndex = 80,
		})
		boot.TextSize = math.clamp(math.floor(H / 45), 12, 24)

		-- stage 2 label: boot manager / kernel log (green, like a console)
		local boot2 = new("TextLabel", root, {
			BackgroundTransparency = 1,
			Position = UDim2.new(0, 24, 0, 20),
			Size = UDim2.new(0.8, 0, 0.6, 0),
			Font = Enum.Font.Arcade,
			Text = "",
			TextColor3 = GREEN,
			TextSize = boot.TextSize,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Top,
			Visible = false,
			ZIndex = 80,
		})
		-- stage 1 footer, like the bottom line of a real BIOS screen
		local biosfoot = new("TextLabel", root, {
			AnchorPoint = Vector2.new(0, 1),
			BackgroundTransparency = 1,
			Position = UDim2.new(0, 24, 1, -20),
			Size = UDim2.new(1, -48, 0, boot.TextSize + 6),
			Font = Enum.Font.Arcade,
			Text = "PRESS DEL TO ENTER SETUP  -  CLICK TO SKIP",
			TextColor3 = Color3.fromRGB(150, 150, 150),
			TextSize = boot.TextSize,
			TextXAlignment = Enum.TextXAlignment.Left,
			Visible = false,
			ZIndex = 80,
		})

		-- stage 1: BIOS POST (typed fast). A function line is drawn live every frame.
		local BIOS_END, BOOT_START = 2.1, 2.22
		local function memtext(t)
			local p = math.clamp((t - 1.15) / 0.5, 0, 1)
			if p >= 1 then
				return "MEMORY TEST : 65536K OK"
			end
			return string.format("MEMORY TEST : %05dK", math.floor(p * 65536))
		end
		local bioslines = {
			{0.45, "UHHHHHH BIOS V" .. UhhhhhhVersion},
			{0.60, "(C) 198X UHHHHHH SOFT INC."},
			{0.95, "CPU ........ ROBLOX R15 60MHZ"},
			{1.15, memtext},
			{1.60, "KEYBOARD .... DETECTED"},
			{1.75, "DISK 0 ...... REANIM-HD"},
		}
		-- stage 2: boot manager, one [ OK ] per service
		local bootlines = {
			{2.20, "UHHHHHH BOOT MANAGER 1.0"},
			{2.40, "[ OK ] LOADING KERNEL"},
			{2.62, "[ OK ] MOUNTING UHHHHHH.SYS"},
			{2.84, "[ OK ] LOADING REANIMATE.SYS"},
			{3.06, "[ OK ] STARTING RAINBOW DAEMON"},
			{3.28, "[ OK ] FEEDING THE CAT"},
			{3.50, "BOOTING NYAN.EXE"},
		}
		local function typedlines(lines, t, speed)
			local shown = {}
			for _, l in lines do
				local n = math.floor((t - l[1]) * speed)
				if n > 0 then
					if type(l[2]) == "function" then
						shown[#shown + 1] = l[2](t)
					else
						shown[#shown + 1] = string.sub(l[2], 1, n)
					end
				end
			end
			if #shown > 0 and math.floor(t * 4) % 2 == 0 then
				shown[#shown] = shown[#shown] .. "_"
			end
			return table.concat(shown, "\n")
		end

		-- scene
		local scene = new("Frame", root, {
			Size = UDim2.new(1, 0, 1, 0),
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Visible = false,
			ZIndex = 2,
		})

		-- ===== flying space cat with a rainbow trail (replaces the old synthwave scene) =====
		-- Built from plain Frames, nothing to download. To use your own cat picture instead of the
		-- little sprite, put PNG files in UhhhhhhReanim/Assets/:
		--   nyan.png                     one still picture, or
		--   nyan1.png, nyan2.png, ...    animation frames (up to 12, played in order, no gif support)
		local IMAGE_FPS = 12          -- speed of the animation frames
